"""Camera-guided sweep controller, operated through the documented Robot client.
All estimates are derived from RGB/depth and camera calibration. No simulator state.
The JSON command log in /app/output/commands.jsonl records the chosen controls.
"""
import sys, json, pathlib
sys.path.insert(0, '/opt/tools')
import numpy as np
from PIL import Image
from rcb_client import Robot

OUT=pathlib.Path('/app/runs')
class Controller:
    def __init__(self):
        self.robot=Robot()
        self.spec=self.robot.spec()
        self.cams=list(self.spec['cameras'])
        self.index=0
        print('SPEC',json.dumps(self.spec),flush=True)
        self.obs=self.robot.get_obs(cameras=self.cams,include_depth=True)
        self.save(self.obs)
    def save(self,res):
        self.obs=res
        path=OUT/f'{self.index:03d}'
        res.save(str(path))
        for cam, arr in res.last.items(): Image.fromarray(arr).save(path/f'{cam}.png')
        print('OBS',str(path),json.dumps(res.meta),flush=True)
        self.index+=1
    def state(self):
        p=self.obs.meta['proprio']; return dict(zip(p['layout'],p['now']))
    def submit(self,actions,note=''):
        self.save(self.robot.submit('ee_delta',np.asarray(actions,dtype=np.float64),dt=self.spec['control_dt'],cameras=self.cams,include_depth=True,video='both',note=note))
    def move(self,xyz,speed=0.4,grip=-1.,settle=10):
        # Move mocap by an explicitly bounded distance, then allow hand tracking.
        p=self.state(); current=np.array([p['mocap_'+a] for a in 'xyz'])
        delta=np.asarray(xyz)-current
        n=max(1,int(np.ceil(np.max(np.abs(delta))/(0.01*speed))))
        action=np.r_[delta/(n*.01),grip]
        actions=np.tile(action,(n,1))
        if settle: actions=np.vstack([actions,np.tile([0,0,0,grip],(settle,1))])
        self.submit(actions,note=f'move mocap to {xyz}')
    def command(self,c):
        with open('/app/output/commands.jsonl','a') as f: f.write(json.dumps(c)+'\n')
        if c['cmd']=='observe': self.save(self.robot.get_obs(cameras=self.cams,include_depth=True,seconds=c.get('seconds',0),video='both'))
        elif c['cmd']=='move': self.move(c['xyz'],c.get('speed',.4),c.get('grip',-1),c.get('settle',10))
        elif c['cmd']=='actions': self.submit(c['actions'],c.get('note',''))
        elif c['cmd']=='repeat': self.submit([c['action']]*c['n'],c.get('note',''))
        else: raise ValueError(c)

if __name__=='__main__':
    controller=Controller()
    for line in sys.stdin:
        try: controller.command(json.loads(line))
        except Exception as exc: print('ERROR',repr(exc),flush=True)
PY
python -u /app/output/gen.py

